(function () {
  function isCanvas(node) {
    return node && typeof node.getContext === 'function';
  }

  function colorOrDefault(value, fallback) {
    return typeof value === 'string' && value ? value : fallback;
  }

  function drawAxes(ctx, width, height, padding, color, yMax) {
    ctx.strokeStyle = color;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding.left, padding.top);
    ctx.lineTo(padding.left, height - padding.bottom);
    ctx.lineTo(width - padding.right, height - padding.bottom);
    ctx.stroke();

    ctx.fillStyle = color;
    ctx.font = '12px Segoe UI, sans-serif';
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    for (var step = 0; step <= 4; step += 1) {
      var value = Math.round((yMax / 4) * step);
      var y = height - padding.bottom - ((height - padding.top - padding.bottom) * (step / 4));
      ctx.globalAlpha = 0.25;
      ctx.beginPath();
      ctx.moveTo(padding.left, y);
      ctx.lineTo(width - padding.right, y);
      ctx.stroke();
      ctx.globalAlpha = 1;
      ctx.fillText(String(value), padding.left - 8, y);
    }
  }

  function drawLegend(ctx, datasets, width) {
    var x = 18;
    var y = 18;
    ctx.font = '12px Segoe UI, sans-serif';
    ctx.textBaseline = 'middle';
    datasets.forEach(function (dataset) {
      ctx.fillStyle = colorOrDefault(dataset.borderColor || dataset.backgroundColor, '#f0be4f');
      ctx.fillRect(x, y - 4, 10, 10);
      ctx.fillStyle = '#e8f0f6';
      ctx.fillText(dataset.label || '', x + 16, y + 1);
      x += Math.min(width / 3, (dataset.label || '').length * 8 + 42);
    });
  }

  function normalizeData(datasets) {
    var maxY = 0;
    var maxX = 0;
    datasets.forEach(function (dataset) {
      (dataset.data || []).forEach(function (point, index) {
        if (typeof point === 'number') {
          point = { x: index, y: point };
        }
        maxY = Math.max(maxY, Number(point.y || 0));
        maxX = Math.max(maxX, Number(point.x || index));
      });
    });
    return {
      maxY: maxY > 0 ? maxY : 100,
      maxX: maxX > 0 ? maxX : 1,
    };
  }

  function drawLineChart(ctx, width, height, datasets, options) {
    var padding = { top: 36, right: 18, bottom: 28, left: 36 };
    var domain = normalizeData(datasets);
    var yMax = options && options.scales && options.scales.y && options.scales.y.max ? options.scales.y.max : domain.maxY;
    drawAxes(ctx, width, height, padding, '#86a5c0', yMax);
    drawLegend(ctx, datasets, width);

    datasets.forEach(function (dataset) {
      var points = (dataset.data || []).map(function (point, index) {
        if (typeof point === 'number') return { x: index, y: point };
        return point;
      });
      ctx.strokeStyle = colorOrDefault(dataset.borderColor, '#f0be4f');
      ctx.fillStyle = colorOrDefault(dataset.backgroundColor, ctx.strokeStyle);
      ctx.lineWidth = dataset.borderWidth || 2;
      ctx.beginPath();
      points.forEach(function (point, index) {
        var x = padding.left + ((width - padding.left - padding.right) * (Number(point.x || index) / Math.max(domain.maxX, 1)));
        var y = height - padding.bottom - ((height - padding.top - padding.bottom) * (Number(point.y || 0) / Math.max(yMax, 1)));
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();
      points.forEach(function (point, index) {
        var x = padding.left + ((width - padding.left - padding.right) * (Number(point.x || index) / Math.max(domain.maxX, 1)));
        var y = height - padding.bottom - ((height - padding.top - padding.bottom) * (Number(point.y || 0) / Math.max(yMax, 1)));
        ctx.beginPath();
        ctx.arc(x, y, dataset.pointRadius || 2, 0, Math.PI * 2);
        ctx.fill();
      });
    });
  }

  function drawBarChart(ctx, width, height, labels, datasets) {
    var padding = { top: 36, right: 18, bottom: 42, left: 36 };
    var values = (datasets[0] && datasets[0].data) ? datasets[0].data : [];
    var yMax = Math.max.apply(null, values.concat([1]));
    drawAxes(ctx, width, height, padding, '#86a5c0', yMax);
    drawLegend(ctx, datasets, width);
    var chartWidth = width - padding.left - padding.right;
    var step = chartWidth / Math.max(labels.length, 1);
    values.forEach(function (value, index) {
      var barHeight = (height - padding.top - padding.bottom) * (Number(value || 0) / yMax);
      var x = padding.left + index * step + step * 0.18;
      var y = height - padding.bottom - barHeight;
      var barWidth = step * 0.64;
      ctx.fillStyle = Array.isArray(datasets[0].backgroundColor)
        ? colorOrDefault(datasets[0].backgroundColor[index], '#f0be4f')
        : colorOrDefault(datasets[0].backgroundColor, '#f0be4f');
      ctx.fillRect(x, y, barWidth, barHeight);
      ctx.fillStyle = '#86a5c0';
      ctx.font = '12px Segoe UI, sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'top';
      ctx.fillText(labels[index] || '', x + barWidth / 2, height - padding.bottom + 8);
    });
  }

  function Chart(node, config) {
    if (!isCanvas(node)) return;
    this.canvas = node;
    this.ctx = node.getContext('2d');
    this.config = config || {};
    this.draw();
  }

  Chart.prototype.draw = function () {
    var rect = this.canvas.getBoundingClientRect();
    var width = Math.max(320, Math.round(rect.width || this.canvas.width || 640));
    var height = Math.max(220, Math.round(rect.height || this.canvas.height || 320));
    this.canvas.width = width;
    this.canvas.height = height;

    this.ctx.clearRect(0, 0, width, height);
    var data = this.config.data || {};
    var type = this.config.type || 'line';
    if (type === 'bar') {
      drawBarChart(this.ctx, width, height, data.labels || [], data.datasets || []);
    } else {
      drawLineChart(this.ctx, width, height, data.datasets || [], this.config.options || {});
    }
  };

  window.Chart = Chart;
})();